            'date'     => '2026-05-29',
            'when'     => 'May 2026',
            'topics'   => ['tms', 'therapy', 'team'],
            'text'     => 'Feel free to open up my report from Anew Era TMS in Laguna Hills and see my improvement so that you can choose to help yourself. I will tell you that my Medicare did cover my treatment and it was very for me to drive there quickly and the parking is easy access to the buildings off Magdeline.
I had gone through a very rough time losing my husband and caregiving him around the clock because of a very aggressive form of melanoma. I lost him and I was paralyzed because my nervous system/brain could not function. I could not wake up, I could not do a thing, I was very confused about many many things, but I did accomplish my goal of giving him the best care possible but because I was always in a fight or flight state, once the caregiving abruptly stopped, my brain and body function was in crisis not to exclude anxiety which comes in many forms so sometimes it’s very hard to identify that’s what holding you. He died on Feb 16, 2026. So I waited before I decided to go to TMS hopefully to see I would get better on my own but it was just too much. So I started TMS in March as you can see and I improved greatly since then, just compare on the chart so you can judge with evidence.
Dallas Flynn was my primary tech but Kris was also there and they are wonderful. Dallas has the type of personality that you would expect from a mental health professional as well as Kris. Her approach is very individualized and she’s extremely conscientious about the welfare of her clients. She’s precise and measures your map, observes you to make sure you are in the best comfort zone as well as the neural path that will be most effective. She has a wonderful personality as a technician and respects boundaries but if you have concerns or you feel confused about anything she urges you to ask questions. This unit is very interested in “the person” they are treating, not just a client. The team works extremely well together and you are covered so there are plenty of people to talk to if you need help.
This unit also has therapists on staff there if you need comprehensive care along with TMS treatment.
I feel soooo much better than when I started. I was truly lost and very frightened about the future regarding myself as well as my own health; These are depressive episodes that can effect everyone even if you think it just doesn’t make sense but we are lucky now to have TMS available now as effective and covered treatment. I feel very relaxed now and I have many plans ahead but yes, I still miss my husband and wish he did not have to suffer, but because these two things can be true in all of our lives at some point, we need to reach out to the experts in the field.
I want to lastly say the the staff at Anew Era TMS in Laguna Hills are women who come with not only technical training but come with addition backgrounds in patients care and ongoing education in the field, so they are highly qualified to make sure you get the best quality care.',
