            'when'     => 'May 2026',
            'topics'   => ['psychiatry', 'team'],
            'text'     => 'I’ve had such a great experience with this doctor’s office. The staff is always so friendly and welcoming, and they really make you feel comfortable from the moment you walk in. They do an amazing job communicating and explaining treatments, medications, and every step of the process in a very detailed and easy-to-understand way. I’ve honestly never had a bad experience here.
