            'date'     => '2026-05-20',
            'when'     => 'May 2026',
            'topics'   => ['tms', 'psychiatry'],
            'text'     => 'I have struggled with depression and anxiety on and off for many years. I’ve tried several different medications, holistic approaches, and have been in therapy for over 15 years.
My primary care provider wanted to place me on medication again, but because of my previous experiences with medications, I wanted to explore other options. She mentioned TMS, so I started researching providers and came across New Era. My first point of contact was Marissa, and she was extremely helpful from the very beginning. She made the process feel easy and helped move everything along quickly.
The process starts with filling out forms, followed by scheduling an evaluation with the psychiatrist. If you are approved, you then schedule your first TMS appointment, where they take measurements of your head to properly position the machine in the area that targets depression. After that, you schedule the rest of your TMS sessions. If you have a busy or complicated schedule, they really do their best to work with you.
I began TMS treatment in March 2026, and it did take some time before I noticed signs that it was helping. I personally started noticing changes toward the end of my sessions. Coming in five days a week can be difficult at times, but I am incredibly thankful for Erika and Marissa.
They have made this experience so pleasant and comforting. They make you forget that you are even receiving treatment. They consistently go above and beyond to make sure you feel supported in every way possible.
I have also worked with their nurse practitioner, Kammie, who has been wonderful as well.
There is parking on-site, and they validate parking, which is very convenient.
If you are debating whether to try TMS, I strongly encourage you to give it a chance. The Long Beach team is truly wonderful, and I’m very grateful for the care and support they have given me throughout this healing journey ❤️‍🩹',
