            'when'     => 'Jan 2026',
            'topics'   => ['psychiatry', 'results', 'team'],
            'text'     => 'The NewEra team, especially Kammie is phenomenal. They believe in the patient health. They listen to your needs and help you with what you need. They respect your boundaries and listen to what you’re telling them. The staff is wonderful, responsive and supportive. They have been the most openly communicative and quick support you than any facility or dr I’ve ever been too! Coming here has been the best decision I’ve ever made when it comes to my health and wellbeing. They don’t force anything on you especially meditation and they encourage you to understand yourself and your body. They don’t go off textbook and what you should take of what you should feel. They listen to you and they go based off of what you want and what you feel compelled with. I’ve had drs before who told me to “keep taking medications” to “that it should help, where I later felt overwhelmed and worse off than I did. That’s not the case here, they analyze every symptom, give you recommendations and tell you what side effects you can feel, and if you’d be comfortable following that treatment plan. They leave it completely up you you and support you. 100000000000000/10 recommend!',
