            'when'     => 'Aug 2025',
            'topics'   => ['tms', 'team'],
            'text'     => 'I love the staff and this location. I have had TMS treatment from several different providers over the last 6 years. This location is closer and more convenient for anyone living in the northwest part of the city. The staff is incredibly friendly and professional.
They did an amazing job working with my insurance and my company HR department to get the necessary approvals and paperwork done.
The machine they use is really cool - the measurements are taken using stereoscopic cameras, and it allows the techs to adjust the coil position to minimize discomfort without missing the target treatment area. No measuring tape being stuck to my head or weird hats. Very efficient setup - I\'m usually in and out of the chair in about 20 mins. There were rarely any delays, so I could count on my appointment being on time - a huge bonus while working.
Update: August 2025 - coming back for another round of treatments and I’m still pleased with the service and the staff. Joseph has been great - taking the time to make sure I’m comfortable and taking a personal interest in me as a patient.',
