            'topics'   => ['tms', 'team'],
            'text'     => 'I can’t say enough good things about Anew Era TMS. From my very first visit, the entire team made me feel comfortable, supported, and truly cared for. Lisa and Brielle are absolute stars. Warm, knowledgeable, and always ready to answer my questions with patience and kindness. Their professionalism combined with genuine compassion made the process so much easier. I always left my appointments feeling heard and encouraged. I highly recommend Anew Era TMS to anyone considering treatment. You’ll be in great hands here.',
