            'date'     => '2025-08-14',
            'when'     => 'Aug 2025',
            'topics'   => ['tms', 'results', 'team'],
            'text'     => '**Edited on 8/14/25 to update** It’s been about 3 years since I had my TMS treatment and I am still depression free! I still often think about all the staff members who helped me through that dark time and hope they’re all doing well! They truly saved my life and I am forever grateful!
If you’re thinking about starting TMS, this is your sign to DO IT!! I just finished my treatment course of TMS and all I can say is WOW!! I’ve always had anxiety my whole life, but when I started grad school it developed into more complex anxiety, panic disorder, and depression. I felt trapped in my own mind and I was just trying to get through the day, every day. Now I feel like I’m actually getting to live again. I feel so much more in control of my life and I’m not constantly being wracked with fear. I feel such a sense of relief and I am so grateful for my tech, Melissa, who was so encouraging and she listened to what I had to say and would advocate on my behalf. She really cares about her patients and wanted me to get relief and she did everything she could to help me and it worked!!! The office is always clean and comfortably designed, and the receptionist, Amber is truly a kind soul. She also genuinely cares about the patients that walk through the door and makes it a point to get to know each one. I was so scared and afraid to do TMS, but thanks to the immense support from the entire team, I finished my whole treatment course and realized how much it changed my life! And I learned that there really was nothing to be scared of. It’s very safe and EFFECTIVE! I’ve also dealt with chronic headaches/migraines and I feel like I’ve had a significant reduction in headaches too since starting treatment. I promise, TMS is worth it. And the staff at Anew Era will be your biggest supporters and they will help you find relief. It will get better, honestly.',
