            'topics'   => ['tms', 'psychiatry', 'team'],
            'text'     => 'I had a truly wonderful experience at Anew Era TMS & Psychiatry in Laguna Hills. I recently completed a full course of TMS therapy, and it made a significant difference in my mental health. I feel lighter, more balanced, and finally like myself again.
