            'when'     => 'Jun 2025',
            'topics'   => ['tms', 'psychiatry'],
            'text'     => 'I am currently about halfway through my TMS treatment plan and have experienced significant improvement in my symptoms of depression and anxiety. I decided to try TMS rather than going through another round of trying to find the correct medication balance that didn’t cause a myriad of side effects. The commitment to come into the office five days a week was the only reason I left the house in the beginning but now I am back at work and even starting to feel like I have the energy to plan for the future. Amber and Melissa have been so kind and caring with me, seeing me through the rough days and encouraging me to keep it up. I would definitely recommend Anew Era TMS to anyone looking for an alternative or supplement to chemical treatment for depression and anxiety.
Update: I returned to Anew Era for another course of TMS in March 2025. Over the last two years, I have experienced significant losses in my family, as well as personal upheaval in my relationships. I knew TMS had a drastically positive effect on my mental health after my mother passed away, so I decided to do it again. Over the course of my treatment, I had several intensely emotional situations and I know I would not have handled them as well as I did without this treatment. Now that I have completed the course, I can honestly say that my anxiety has diminished greatly and my mood improved. I had an immediate improvement in my sleep, which helps so much with everything else. I was taken care of by Danni and Sarah, who were wonderful TMS techs. They always made me feel welcome and comfortable. I would highly recommend Anew Era Psychiatry and TMS to anyone struggling with their mental health!',
