            'date'     => '2025-05-23',
            'when'     => 'May 2025',
            'topics'   => ['tms', 'therapy', 'psychiatry', 'results', 'team'],
            'text'     => 'I didn\'t know what to expect when I first came . I just knew I needed help with mental health and my Dr felt this was the place for me to receive it . This has been the best decision I have ever made . I feel seen and I know that I\'m being heard . They have gone above and beyond for me and I genuinely feel like they care about me and my well being . I come here for medication management (she is so patient with me and listens to what I have to say and if something doesn\'t work she works with me to figure out what\'s the next best thing ), I also receive talk therapy here (I\'ve never been so excited to have a therapy session . She won me over with our first meeting . I got off our zoom call feeling like I had just received the biggest hug . I\'m literally counting down the days to our next session). Lastly I also receive TMS therapy here . My technician is Joseph most of the time but I\'ve also seen Brianna . They have made this experience amazing for me . Constantly checking on me and talking to me and just letting me know that while I\'m there , I\'m their main focus . As a mother , I can admit I\'ve forgotten to focus on myself so to have this time that it\'s all about me is very refreshing . This week we even had a cute little bingo game that made me take some extra steps to being more proactive in getting better . Even if I don\'t win I\'m just excited to fill in the squares. Even the wonderful woman at the front desk is amazing . I\'m always greeted with a smile and anytime I\'ve called I\'ve gotten an answer (and you can hear her smiling over the phone ). I said allllll this to say that I\'m glad I took this step , I feel so blessed that there is a group of people that care about me and my well being , and I would recommend this place to EVERYONE. They are all truly God sent .',
