            'topics'   => ['tms'],
            'text'     => 'Honestly, I have been struggling with anxiety and depression since I was a teenager, and a few months ago, I was at the end of my rope. Panic attacks every day, nonstop crying, etc. As a last ditch attempt, I agreed to try TMS, and oh dear God, I am human again. Six weeks in, two or three to go, and I feel like a person. I have my life back and even my loved ones, friends, coworkers have all noticed.
