            'when'     => 'May 2025',
            'topics'   => ['tms'],
            'text'     => 'My experience here at Anew Era Tms has been nothing short of spectacular. The team showcases to me in every appointment they are both professional and personable. I would like to give a shoutout to Mitcma as she has been the primary tech in charge of my treatment. She has made what began as a daunting experience turn into an experience that sometimes I look forward to. Due to Mitcma and the rest of the TMS team my daily life has become a bit more manageable and for those who struggle you know that little bit goes a long ways.
Thank you!',
        ],
        [
            'name'     => 'Michael F.',
            'initials' => 'MF',
            'clinic'   => 'central-austin',
            'city'     => 'Central Austin, TX',
            'source'   => 'Google',
            'date'     => '2025-05-09',
            'when'     => 'May 2025',
            'topics'   => ['tms', 'psychiatry', 'team'],
            'text'     => 'I\'ve really only had TMS at Anew Era, so I can\'t really speak to their psychiatry services. I did meet with one of their psychiatrists, Prasanna, once for a second opinion on my various treatment options. It was a pleasant experience, but I ultimately ended up going back to my regular psychiatrist.
That being said, I had a great experience with the TMS process and would recommend Anew Era. I was really nervous about the treatment at first because it\'s such a big commitment and so different than anything else I\'ve tried for my depression, anxiety, OCD, and complex PTSD. The patient coordinator and clearance doctor were both great about answering any questions I had and walking me through the process. The techs also went out of their way to make me feel comfortable and at ease.
Something I especially appreciated was the flexibility in scheduling. My schedule fluctuates wildly from week to week, but Anew Era was willing to work with me on that, and I never had a problem finding appointments that fit my schedule. Even last-minute changes could usually be accommodated, and having the clinic open on certain Saturdays was a great back-up option.
At the end of the day, sadly I can\'t say I personally got significant benefits from the treatments. I feel mostly the same as I did before, but your mileage will definitely vary. I highly encourage anyone who\'s on the fence about TMS to give it a try with Anew Era. It definitely felt less intimidating after the first few sessions, and they really go out of their way to ensure you feel comfortable both physically and mentally.
Shout-out and thank you to my care coordinator Soha; clearing doctor Dr. McIntyre; techs Alex, Elise, and Haley; and the receptionist Robin...thank you all for being there with me every step of the way!',
