            'date'     => '2024-11-08',
            'when'     => 'Nov 2024',
            'topics'   => ['psychiatry'],
            'text'     => 'I’ve been with Barbara Reed for over a year now, and she’s made such a huge difference in my life. She’s really easy to talk to and actually listens to what I’m saying. When we started out, it took a few tries to get my meds right, but she was super patient. She kept checking in, adjusting things as we went along, and never made me feel like my concerns were brushed off.
When my first medication caused weight gain, we talked about it, and she switched things up until we found something that worked without the side effects. Same with my ADHD meds—she took her time to find the right dosage and even gave me a plan that lets me adjust based on how I’m feeling each day. She also understood how my body might react differently depending on the time of the month, which was honestly something I never thought about before.
My last doctor would just throw out suggestions like “try drinking more water” or “get some sunshine” when I told him things weren’t working. That left me feeling like he didn’t really get what I was going through. With Barbara, I feel heard and supported, which has made a world of difference for me.
If you get a chance to see her, I highly recommend it. She’s the kind of provider who actually cares, and that’s rare.',
