            'topics'   => ['tms', 'psychiatry'],
            'text'     => 'This was my first time to try TMS and I really appreciate this TMS treatment. I contacted a few TMS & Psychiatry clinics but Anew Era TMS & Psychiatry - Laguna Hills office treated me completely different compared to the other TMS & Psychiatry clinics.
