Denise was also the same. She always welcomed me and made sure I was okay. She introduced to me some relaxing YouTube channel to watch while having TMS treatment. She also gave me some advice on how to handle my stress in daily life as well. Her life experiences and knowledge shaped and taught my brain how to handle difficulties.
