            'text'     => 'The staff are amazing and truly care for their patients. I was very skeptical at first but they were always able to answer questions and made me feel comfortable from day one. They were always very accommodating of my schedule and responded very quickly to any messages. The office was always super clean and welcoming. Brittany, Briana, and Kim all treated me and are all fantastic at what they do and treated me like family. I couldn\'t recommend them enough. My only complaint has nothing to do with the treatment or staff- halfway through my treatments at the Sugar Land location that office was closed and I had to drive to Cypress or Katy for the remainder of the treatments. Having the location in Sugar Land was incredibly convenient and was one of the main factors when I was researching TMS therapy. My suggestion would be to bring back a location closer to Sugar Land/Richmond/Rosenberg. I wish I could recommend some of my friends in Sugar Land to go there but the drive is so difficult now without the SL location.',
