            'text'     => 'I was anxious and worried about my first appointment but the staff made me feel very welcome. The intake specialist Dahlia and Doctor Rhoda were so easy to talk too and were very patient with me. They showed concern and understood through experience in the profession, what I was dealing with. Glad I found them.. I\'m much more at ease now.',
