            'date'     => '2024-04-09',
            'when'     => 'Apr 2024',
            'topics'   => ['tms'],
            'text'     => 'This is my first time getting TMS treatment. I was excited, yet apprehensive because I didn’t know what was in store for me as I was not very familiar with TMS, although I have heard of it. After meeting with Sandy and Juliet, they made me feel so comfortable and answered all of my questions that I was comfortable proceeding with the treatment. Let me tell you I had the best experience, not only was I made to feel comfortable and anytime anything came up that I had questions on, they were fully answered, and I developed a really nice rapport with Juliet and we got along great! After my sessions came to an end, I could not believe how much it helped me. It made me quite emotional when I began noticing a difference with my depression and my anxiety after only a couple weeks! Not only did it help me in these two areas but it also helped me with some of my PTSD. My triggers have really settled down a lot and that is a huge benefit for me! I highly recommend TMS treatment through New Era, TMS for anyone who is struggling with depression and or anxiety. This is an amazing place to go to. You’ll always feel safe and comfortable throughout the process. Thank you so much Sandy and Juliet for such a great experience, I am forever grateful. Blessings on you both.',
