            'topics'   => ['therapy', 'psychiatry', 'results', 'team'],
            'text'     => 'I truly cannot say enough good things about this office. Their staff is absolutely wonderful. You can tell they truly want all of their clients/patients to get better. I’ve been struggling with my mental health since I was a child and finding this office has saved my life. I have had two different Psychiatrist and I was a huge fan of them both and I just started with one of their therapist. (He’s amazing) They don’t get upset when I mess up and stop taking my meds and they always push you to make it to your appointments. Not because they want the money, but because they care about you. For example, last week I almost missed my therapy appointment because I didn’t see the email and my dumb depressed brain said, ‘you don’t need to go’. Well the front desk called me twice and made sure I jumped on that call even if I was 5 minutes late. Because they believe in healing. I could keep going, but I’ll chill out. I’m just obsessed with this place.',
