            'when'     => 'Jan 2024',
            'topics'   => ['tms', 'team'],
            'text'     => 'I never thought TMS would be an option for me due to the cost, but I met my deductible last year so my treatment was covered. From day one the staff at Anew Era were helpful, patient, and easy to communicate with. My technician, Brianna, was so nice and made everything very easy for me. She was flexible with my schedule; I work Monday-Friday and could only come on my lunch breaks and did not have any trouble scheduling my treatments. At about 24/36 sessions I could feel that it was making a difference! Highly recommend pursuing TMS here!',
