            'date'     => '2024-01-15',
            'when'     => 'Jan 2024',
            'topics'   => ['tms', 'team'],
            'text'     => 'The North Mopac staff are phenomenal!!! I highly recommend A New Era TMS due to their exceptional staff and great care quality. I cannot say enough good things about Adriana Corralejo. She made herself very available, stayed late to work on my insurance authorization, made me feel at ease by providing frequent updates, was respectful and went out of her way to help me with my insurance authorization! Adriana really is incredible and I admire her work ethic and how much she cares about her patients. I accidentally submitted an outdated insurance but she never made me feel bad, was so on top of following up daily, and did all the work by herself, without making me take extra steps to help (even though it was my fault). If Adriana is coordinating your TMS treatments, you will be in great hands!
The technicians at A New Era are outstanding as well! Angel and Zayra were very attentive, friendly, and would come in early and accommodate my schedule if needed. They are reliable employees who always had my favorite TV show prepared when I got there. Also, Pia is very sweet and goes above and beyond to make her patients feel cared about! She genuinely cares and would remember things I told her weeks ago and follow up with me. Pia is outstanding and so are the other technicians that I couldn\'t recall their specific names. Jerry also cares about the patients and made it a point to greet me by name everyday and follow-up about previous conversations. He always made my day a little better when I saw him up front. All around great staff! The staff is really what makes up any mental health provider office, and they go out of their way to make patients feel comfortable and cared about! Highly recommend the North Mopac A New Era TMS location!',
