            'date'     => '2023-12-04',
            'when'     => 'Dec 2023',
            'topics'   => ['psychiatry', 'team'],
            'text'     => 'Hello, I am a patient of Bryan Walker and I highly recommend his services, being diagnosed bipolar has its many complications but with the help of Dr. Walker I have been able to overcome a lot of these complications. Now he isn’t a “cure all” individual, but with mental health, it never is in any way. He has amazing insight and is very knowledgeable of mental disorders and medication. He has helped me tremendously with understanding my disorder and providing factual information of my medication which has allowed me to find medication that is most suitable for me. He is very cooperative and responsive, and willing to work with you if you have any concerns or scheduling difficulties, and also the people who work at the front desk. Overall they have an amazing operation that is adaptive and suitable to all your medical needs, I highly recommend seeking treatment from here, they are a very considerate and a well knowledgeable group of people who are there to support you through your medication journey.',
        ],
