            'topics'   => ['tms', 'psychiatry'],
            'text'     => 'Thoroughly happy with my experience at Anew Era TMS in West LA! I\'ve struggled with moderate depression for over a decade and most prescription medication I tried didn\'t really help. I finally found medication that made a dent in my depression, but I was also ready to try alternative therapies like TMS, Ketamine, etc. Long story short, I just completed my TMS therapy with them and I feel a notable (positive) difference! I feel more like the person I was before the depressive episode hit over a decade ago. I\'m interested in people and hobbies once again. I feel hopeful. The combination of TMS + medication turned things around for me. The support they provide is great. A huge "thank you" to Nayshelle, Marissa, Victoria, and Jessica for their kindness and responsiveness. Marissa was my personal TMS administrator/coordinator and she is a joy to work with. She has a wonderful bedside manner and always made sure that I was comfortable and that my experience was nothing short of pleasant. She was an active part of my TMS journey. Thanks again Marissa!',
        ],
