            'text'     => 'I love coming to my TMS sessions. My technician Roshan has made me comfortable from the very first time I stepped into the treatment room. Roshan is very professional, knowledgable, explains everything in detail and makes me feel at ease. He always makes sure that I am comfortable with the strength of the magnetic pulses I am receiving. I feel that he really cares about his patients and wants them to get better. I love his positivity and encouragement.
