        [
            'name'     => 'Hayley G.',
            'initials' => 'HG',
            'clinic'   => 'torrance',
            'city'     => 'Torrance, CA',
            'source'   => 'Google',
            'date'     => '2022-12-01',
            'when'     => 'Dec 2022',
            'topics'   => ['tms', 'therapy', 'psychiatry', 'team'],
            'text'     => '(This is a TMS-focused review)
I was referred to TMS by both my psychiatrist and my therapist at Anew Era. I\'ve tried half a dozen different medications and crashing from withdrawal from one of them, I was sort of at my wit\'s end treatment-wise. That\'s what prompted me to take the leap and try TMS.
The approval process was pretty simple. I sat down with Cherish who explained the treatment, the time frame, the expected cost, and the process to get treatment approved by insurance. A few days later, I had a video consult with the doctor who then submitted my request to my insurance. I got approved a few days later and started treatment the next week.
The treatment itself took a little getting used to. I\'m a pretty physically sensitive person, so we started the intensity low and took it up bit by bit. Any time the intensity was too much for that day, we\'d just step it back down and try again later. I started feeling the positive results about 3 weeks into treatment, which I think can be attributed to TMS as well as my current Rx kicking in.
The staff were SO accomodating and reassuring from my initial consult, to evaluation, and all throughout treatment. They all have a genuine heart for their patients and bend over backward to make sure you\'re comfortable and understand the treatment. My technicians, Juliet and Cherish, were the freaking BEST. I looked forward to going to treatment every day to get to shoot the breeze with them.
If you\'re looking for a sign to try this treatment - this is your sign!! I was nervous about taking the leap, but I would recommend TMS to anyone thinking about it.',
