            'text'     => 'Having Anxiety, PTSD, and depression my whole life combined with the horrendous year and multiple great losses this year, I found myself in a place that I didnt feel I could go on. As soon as I realized this was not where I should be mentally, I started on a journey to find help. My first call was insurance and I was leaning very heavy on getting admitted to mental health facility... However, I was pretty admitant about not wanting to just be thrown on meds to mask my symptoms. So I sought out other treatment modalities and found TMS. Through lots of research and many phone calls, and lots of breakdowns, I found myself speaking to the staff members here at Anew Era. I was skeptical about signing up for 36 treatments... Thats a whole lot when I wanted to just give up. But I went. After the first couple of days, I really did not want to go. And thankfully I had my husband next to me being supportive and reminding me this was temporary. I then met Adriana. Her primary role was not to be a tech, but she made me feel comfortable and allowed me space if I wanted to talk or sit in silence. Which I very much needed her. She was the only thing that kept me going back every day, aside from knowing that I needed to be there. I noticed a handful of weeks in that I was feeling better and feeling more like myself and as time went on I noticed that I wasnt just back to my normal, but that I was making huge progress in other areas. Being able to advocate for myself and not be jumpy (which is something that Ive had for as long as I can remember) and also I would get nervous/anxious before leaving my house and would have to pee like 10 times before I could leave... and it stopped. I would say that TMS helped me tremendously and would recommend to anyone. I would also like to point out that TMS was not the only therapy I was getting. I have been in traditional trauma psychotherapy for 5 years and continued that, i also started with an EMDR therapist and was seen by a psychologist and changed my supplements and practicing grounding and mindful meditation. So I was putting in a lot of work along with taking a leave of absense from work. All that said, those other things helped a lot too, but I just dont think I would have made as much progress without TMS or with out Adriana!',
        ],
