            'text'     => 'First appointment with Tiffany, she was so compassionate, and very insightful into medications that I have not tried and what may work for my mental health. I left feeling at ease that although I’m in a place where I have little hope, she was able to give me some optimism that whatever we can do to help me get my life back, we will do. Highly recommend Tiffany!',
