            'when'     => 'Aug 2022',
            'topics'   => ['psychiatry'],
            'text'     => 'This office is incredible. Every single person I’ve interacted with has been so sweet and helpful and understanding. They make everything so easy. I’m under the care of Tiffany Nix, and I’ve had 2 psychiatrists before her (at different offices) who were just absolutely awful compared to her. The offices themselves were incompetent and rude, that’s been my experience anyway. This place and Tiffany are so different. They actually care, you can tell that it’s not just a job to them. She truly listens to me, and it’s obvious she is passionate about helping people and has your best interests in mind. She also takes the time to explain everything so well; I don’t feel like “just a number” where they’re trying to get rid of me as soon as possible to move onto the next patient. All of the employees here are that way! They take their time to help you. I’ve interacted dozens of times with many different people at this office and every single occasion has been a calming, joyful experience. Which is rare for me due to all of my diagnoses, and my struggled search to find help. I’m really grateful for them, and I highly recommend everyone searching for psychiatric/mental health care to check them out!! Also- they’re currently offering zoom sessions so if you’re far away like I am (about an hour without traffic!), that’s not a problem. I believe this might be temporary due to covid but not sure! Just throwing it out there. Good luck to anyone reading this, I hope you find the help you’re looking for!',
