            'text'     => 'I’ve would recommend Anew Era TMS to anyone in need of caring, personalized, responsive mental health care. My experience as a patient has been nothing but positive.',
        ],
        [
            'name'     => 'Taylor G.',
            'initials' => 'TG',
            'clinic'   => 'torrance',
