            'source'   => 'Google',
            'date'     => '2022-07-12',
            'when'     => 'Jul 2022',
            'topics'   => ['tms', 'psychiatry'],
            'text'     => 'I HIGHLY recommend doing TMS at Anew Era. Especially the Torrance location because Amanda is just so wonderful. I originally came in just to get a psychiatrist and am so glad I started TMS. I\'ve already made so much progress and cant wait for continual improvement. Thank you so much Dr. Manurung!
Update 12/13/21: I finished my TMS 12/3 and am just ecstatic about my results. It’s absolutely amazing what it has done for me. I make decisions easier. I rationalize better. I have more interest in other people now. The images and colors inside of my head are even brighter. I feel less of a need to seek out things and activities that make me happy because I am already content within my mind. Going through this and therapy together has shaped me more in a month and a half than I could have ever imagined.
I was so convinced I\'d suffer from headaches--never happened. I was nervous about being in pain during treatment--didn\'t happen. I was skeptical I\'d be able to make it to all 36 treatments--I loved having this routine. I was so sure I wouldn\'t be able to tell the difference--I couldn\'t have been more wrong.
I recommend this to anyone and everyone suffering from any amount of depression. 12/10 experience and results. A million thanks to Anew Era, but mostly to Amanda at the Torrance location!
Update 7/12/22: Just 4 sessions away from finishing my 2nd round of TMS and I am truly amazed by this technology all over again. You can definitely notice a difference in yourself pretty quickly, but it\'s at the 7 week mark that my life has almost made a FULL 180. I can tell by the way I am ready to start my remote job first thing in the morning instead of avoiding it. I can tell by the way I feel positively about going to bed at night. I could even tell in my Snapchat memories right around that 7 week mark because I began singing into the camera more and even taking more selfies.
I say all of that to say-- I don\'t just ~feel~ better, I feel more myself as someone who normally loves my job, LOVES my bed, and loves mySELF. I lose so many basic, yet crucial, character traits due to depression and anxiety and TMS gives them back to me. Eternally grateful for Amanda and Anew Era.',
