            'text'     => 'The staff is here is so great, very welcoming, and they make is really easy to get comfortable.
The techs are kind, and I love that they like to engage in conversation. I\'ve had 4 techs assist me, all which were great. During treatment they make conversation about the shows that I\'m watching, or how the day\'s been going.
Yesi is who\'s worked with me the most, and she\'s so straightforward with me about being honest about how I\'m feeling, what symptoms I\'m experiencing, and even about any discomfort during the treatment. I just recently started treatment on the right side, and I was feeling a little discomfort (for which, out of habit with Yesi) I told Sydney, and she was making adjustments to ensure I wasn\'t feeling any more pain. She also marked it on my cap so other techs would know. When I saw Yesi my next session I told her I felt dizzy after my session, but thought it was probably vertigo. She told me to *always* let them know what I\'m feeling, because it\'s the body\'s way of saying something\'s not right. She made some more adjustments, and it\'s been good since. I usually don\'t like to be a bother, and say something, but Yesi keeps me on check. :)',
