            'topics'   => ['tms', 'team'],
            'text'     => 'The staff here is great, but it was Anthony, my TMS tech, who really made this experience personalized and comfortable. Anthony is an absolute professional when it comes to directing that magnetic coil at your head. He understands that a small manipulation of the machine makes all the difference in how the treatment feels to the patient and he’s willing to take the time to ensure your comfortable at every single session. Truly, cannot say enough about how wonderful Anthony is.',
