        ],
        [
            'name'     => 'L C.',
            'initials' => 'LC',
            'clinic'   => 'cedar-park',
            'city'     => 'Cedar Park, TX',
            'source'   => 'Google',
            'date'     => '2021-04-23',
            'when'     => 'Apr 2021',
            'topics'   => ['tms', 'psychiatry', 'team'],
            'text'     => 'Recently moved to Texas and needed to get established with a new provider and after doing my own research I found Anew Era TMS & Psychiatry. Having suffered with depression and anxiety for a while and going through therapy and searching for the right medication that would work with my chemistry has been very difficult to say the least. It’s affected my job, my home life and the relationships I have with people. I’ve honestly felt hopeless for many years and despite doing the things that should help me to feel “better”, it just wasn’t working. I made my initial therapy appointment and honestly didn’t expect it to be anything different than I’ve done before, but after my first session with the PA, Jessica Batten, I felt relieved to have a physician that heard all the things I was saying and offered solutions that might be beneficial to my particular situation. She is kind and thoughtful and most importantly really listens. She is definitely someone whom I will continue to seek care with. Going into my first appointment I was not privy to what “TMS” was or what it could do for me, but after greater explanation and a subsequent appointment with the specialist who handles the therapy, I thought what’s the worst it can do. Nothing I’ve done up to this point has been working so I went in with an open mind and committed to the 5-6 weeks of treatment that would hopefully help relieve some of my symptoms. I don’t think I can actually convey into words how thankful I am for all that TMS has done for me. To have an “ah-ha moment and realize myself that the things that used to make me super anxious or depressed before no longer have a tight grip or vice on every aspect of my life, makes me feel like I’ve begun a new life and have started over! I don’t feel like the weight of the damn world is on my shoulders anymore. Don’t get me wrong, I still worry but it no longer consumes my every thought. It no longer has a seat at my table and on days that it decides it wants to try, I feel like I have the tools to handle it and also not allow it to linger like it used to.
I also would love to highlight some of the techs that provided the daily TMS therapy for me. It’s incredibly hard to put some of your deepest feelings out to someone you just met. Talking about why your depressed or anxious is so hard, or at least is for me. I honestly cannot say enough about Ms. Celinda. She was one of my techs for a good portion of my sessions and she made me feel like I was a friend of hers that I had known my whole life. She is compassionate and genuine when you converse with her and made me feel at ease and comfortable, especially on days that were hard for me to be there mentally. She truly cares about her patients!
I also would like to give kudos to Mr. Gerardo as well. His mild manner, and compassion he has for others shines through when he converses with you before, during, and after your sessions.
I highly recommend the Cedar Park office and staff! You all made me feel like I finally have an
old part of me back that I’ve tried finding for a long time! From the bottom of my heart, thank you!!',
        ],
